define :wim_play_voice_event do |role, note_value, duration, velocity|
  if (wim_layer_enabled_for_role role) and (get(:active_piece) == :wim)
    synth_name, role_amp, release_scale, transpose, pan_value=wim_voice_config role
    use_synth synth_name
    amp_value=wim_clamp_value(velocity, 0.04, 1.0)*role_amp.to_f*get(:wim_master_amp).to_f
    release_value=[[duration.to_f*release_scale.to_f, 0.05].max, 6.0].min
    play note_value.to_i+transpose.to_i,
         attack: 0.005,
         release: release_value,
         amp: amp_value,
         pan: pan_value.to_f
  end
end

define :wim_play_rhythm_event do |note_value, velocity|
  if (get(:wim_layer_rhythm) == true) and (get(:active_piece) == :wim)
    style=get(:wim_current_style)
    midi_note=note_value.to_i
    if style==:vocaloid_electro
      if [35, 36].include?(midi_note)
        sample_name=:elec_soft_kick
      elsif [38, 40].include?(midi_note)
        sample_name=:elec_hi_snare
      elsif [42, 44].include?(midi_note)
        sample_name=:elec_tick
      else
        sample_name=:elec_cymbal
      end
      style_amp=0.40
      cutoff_value=116
    else
      if [35, 36].include?(midi_note)
        sample_name=:bd_haus
      elsif [38, 40].include?(midi_note)
        sample_name=:sn_dub
      elsif [42, 44].include?(midi_note)
        sample_name=:drum_cymbal_closed
      elsif [46, 49, 52, 55, 57].include?(midi_note)
        sample_name=:drum_cymbal_open
      else
        sample_name=:drum_tom_mid_soft
      end
      if style==:piano_pop
        style_amp=0.24
        cutoff_value=96
      else
        style_amp=0.52
        cutoff_value=123
      end
    end
    amp_value=wim_clamp_value(velocity, 0.04, 1.0)*style_amp*get(:wim_master_amp).to_f
    sample sample_name, amp: amp_value, cutoff: cutoff_value
  end
end

define :wim_perform_event_track do |events, role, total_beats|
  cursor=0.0
  events.each do |event|
    start_beat, duration, note_value, velocity=event
    wim_wait_music_beats start_beat.to_f-cursor
    wim_wait_until_playing
    if role==:rhythm
      wim_play_rhythm_event note_value, velocity
    else
      wim_play_voice_event role, note_value, duration, velocity
    end
    cursor=start_beat.to_f
  end
  wim_wait_music_beats total_beats.to_f-cursor
end

